exercises.solution:
def margin_flag(equity: float, requirement: float, mta: float = 10_000) -> str:
    """Classify an account's margin position vs its requirement."""
    if requirement == 0:
        return "NO_REQ"
    shortfall = requirement - equity
    if shortfall >= mta:
        return "CALL"
    if shortfall > 0:
        return "SMALL_SHORT"
    return "OK"

