from datetime import date

BASIS_DAYS = {"ACT/360": 360, "ACT/365": 365}

def interest(principal, rate, start, end, basis="ACT/360"):
    if basis not in BASIS_DAYS:
        raise ValueError(f"unsupported basis: {basis}")
