from math import log, sqrt, exp
from statistics import NormalDist
N = NormalDist().cdf

def black76(F, K, T, sigma, r, kind="call"):
    d1 = (log(F / K) + 0.5 * sigma**2 * T) / (sigma * sqrt(T))
    d2 = d1 - sigma * sqrt(T)
    df = exp(-r * T)
    if kind == "call":
        return df * (F * N(d1) - K * N(d2))
    return df * (K * N(-d2) - F * N(-d1))

