from collections import defaultdict, deque

def within_hops(edges, start, max_hops):
    g = defaultdict(list)
    for a, b in edges:
        g[a].append(b)
        g[b].append(a)
    dist = {start: 0}
    q = deque([start])
    while q:
        n = q.popleft()
        if dist[n] == max_hops:
            continue
        for nb in g[n]:
            if nb not in dist:
                dist[nb] = dist[n] + 1
                q.append(nb)
    return sorted(n for n in dist if n != start)

