def breaching_clients(events, limit):
    windows = defaultdict(deque)
    breached = set()
    for t, client in events:
        w = windows[client]
        w.append(t)
        while w and w[0] <= t - 60:
            w.popleft()
        if len(w) > limit:
            breached.add(client)
    return sorted(breached)

